// Sync the catalog from the upstream ERP/PIM. Implemented as an inline Server
// Action so it can be wired to a plain HTML <form action>.
//
// revalidateTag('products', 'max') uses a stale-while-revalidate profile: it
// marks the catalog cache entry stale and returns immediately without blocking
// the response or forcing a re-render. Subsequent reads across any view that
// depends on the "products" tag keep serving the (briefly stale) cached data
// while a fresh fetch runs in the background, then pick up the updated data on
// the next read. This keeps the admin responsive even when a sync touches
// thousands of SKUs.
async function syncCatalog() {
  'use server'
  revalidateTag('products', 'max')
}

export default async function CatalogPage() {
  const products = await getCachedProducts()

  return (
    <main style={{ padding: 24 }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          gap: 16,
          marginBottom: 24,
