      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '8px 0 0', color: '#666' }}>
            Cached catalog data. Sync pulls the latest pricing, inventory, and
            availability from the ERP/PIM.
          </p>
        </div>

        {/* Regular HTML form wired to an inline Server Action. Submitting
            triggers the background refresh without blocking the page. */}
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>

      <table style={{ borderCollapse: 'collapse', width: '100%' }}>
