            <tr key={product.id}>
              <td style={cell}>{product.id}</td>
              <td style={cell}>{product.name}</td>
              <td style={{ ...cell, textAlign: 'right' }}>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

